-- | Whether a syntax kind is trivia (@%trivia@).
isTriviaSyntaxKind :: PegRt.SyntaxKind -> PegPrelude.Bool
isTriviaSyntaxKind peg'k = PegPrelude.elem peg'k [syntaxKindWs, syntaxKindInd, syntaxKindComment]

